{
  "title": "Which city?",
  "width": 900,
  "height": 130,
  "controls": [
    { "type": "label", "label": "How to use", "text": "Type a city and pick a start year, then run the data cell (▶) and the analysis cell below it.", "x": 0, "y": 0, "width": 900, "height": 44 },
    { "type": "text", "label": "City", "bind": "research_city", "default": "London", "placeholder": "Any city or town", "x": 0, "y": 54, "width": 300, "height": 64 },
    { "type": "slider", "label": "Start year", "bind": "research_from", "default": 1950, "min": 1950, "max": 1990, "step": 1, "x": 330, "y": 54, "width": 300, "height": 64 }
  ]
}

// Find the city, then fetch every day's mean temperature from the Open-Meteo
// archive. models=era5 keeps the whole record from one consistent source, as
// Open-Meteo's documentation advises for decades-long trends.
const city = String(nb.get('research_city') ?? 'London').trim() || 'London';
const firstYear = Number(nb.get('research_from') ?? 1950);
const lastYear = new Date().getFullYear() - 1;            // the last complete year

const found = await fetch(`https://geocoding-api.open-meteo.com/v1/search?name=${encodeURIComponent(city)}&count=1`).then((r) => r.json());
if (!found.results?.length) throw new Error(`Couldn't find a place called "${city}". Check the spelling in the City box.`);
const { name, country, latitude, longitude } = found.results[0];

const url = 'https://archive-api.open-meteo.com/v1/archive'
  + `?latitude=${latitude}&longitude=${longitude}&start_date=${firstYear}-01-01&end_date=${lastYear}-12-31`
  + '&daily=temperature_2m_mean&models=era5&timezone=auto';
const response = await fetch(url);
if (!response.ok) throw new Error(`The Open-Meteo archive answered ${response.status}. Wait a minute and run this cell again.`);
const data = await response.json();

// Average each year's days.
const totals = {};
data.daily.time.forEach((day, i) => {
  const t = data.daily.temperature_2m_mean[i];
  if (t === null) return;
  const year = day.slice(0, 4);
  totals[year] ??= { sum: 0, days: 0 };
  totals[year].sum += t;
  totals[year].days++;
});
const years = Object.entries(totals).map(([year, { sum, days }]) => ({ year: Number(year), mean: Math.round((sum / days) * 100) / 100, days }));

nb.set('city_climate', { city: name, country, latitude, longitude, first_year: firstYear, last_year: lastYear, years, source: 'Open-Meteo Historical Weather API, ERA5' });

const warmest = years.reduce((a, b) => (b.mean > a.mean ? b : a));
const coolest = years.reduce((a, b) => (b.mean < a.mean ? b : a));
const days = years.reduce((sum, y) => sum + y.days, 0);
const esc = (text) => String(text).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]);

return `
<div style="background:#0f172a;color:#e2e8f0;font:14px/1.6 system-ui,sans-serif;border-radius:12px;padding:14px 18px">
  <div style="font-size:18px;font-weight:700;color:#f8fafc">${esc(name)}, ${esc(country)}</div>
  <div style="color:#94a3b8">${latitude.toFixed(2)}°, ${longitude.toFixed(2)}° · ${years.length} years, ${days.toLocaleString()} days of ERA5 data via Open-Meteo</div>
  <div style="margin-top:8px">Warmest year: <b style="color:#f87171">${warmest.year}</b> (${warmest.mean.toFixed(1)} °C) · Coolest year: <b style="color:#60a5fa">${coolest.year}</b> (${coolest.mean.toFixed(1)} °C)</div>
</div>`;
